      "content": "/**\n * dsh-lsp-kotlin smoke e2e. Three lanes:\n *\n *  1. `pack defaults` — offline config assertions (always run).\n *  2. `missing server` — offline fallback assertion (always run): with an\n *     unresolvable command the pack still loads and queries fail with the\n *     structured LSP_UNAVAILABLE error, so other tools keep working.\n *  3. `real server` — the lsp tool’s four operations against a sample file;\n *     skipped automatically when the language server is not installed.\n */\n\nimport { afterAll, beforeAll, describe, expect, it } from 'vitest'\nimport { mkdtemp, mkdir, realpath, rm, writeFile } from 'node:fs/promises'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { spawnSync } from 'node:child_process'\nimport { Context } from '@deepseek-ai/cordis'\nimport Lsp from '@deepseek-ai/dsh-lsp'\nimport type { LspQueryRequest, LspQueryResult } from '@deepseek-ai/dsh-lsp'\nimport LocalSubprocessRuntime from '@deepseek-ai/dsh-subprocess-local'\nimport LocalFileSystem from '@deepseek-ai/dsh-fs-local'\nimport * as Pack from '../src/index.ts'\n\n/** Probe whether the language server binary truly runs. */\nfunction probeServer(command: string): boolean {\n  const probe = spawnSync(command, ['--version'], {\n    encoding: 'utf8',\n    timeout: 10_000,\n    shell: process.platform === 'win32',\n  })\n  // Spawn failure or timeout (ENOENT / killed) never counts as installed.\n  if (probe.error !== undefined || probe.status === null) return false\n  if (probe.status === 0) return true\n  // Some servers (e.g. sourcekit-lsp) reject `--version` with a usage error while\n  // running fine; only output saying the binary itself is missing skips the lane\n  // (this also skips a rustup shim whose component is not installed).\n  const output = String(probe.stdout ?? '') + String(probe.stderr ?? '')\n  return !/(no such file|not found|unknown binary|command not found|ENOENT)/i.test(output)\n}\n\nconst installed = probeServer('kotlin-language-server')\n\nconst prebuild = null\n// `built` flips in beforeAll when a pack declares a prebuild (e.g. `swift build`);\n// build-dependent operations skip when it fails.\nlet built = prebuild === null\n\n// Lane 1: pack defaults ------------------------------------------------\ndescribe('dsh-lsp-kotlin pack defaults', () => {\n  it('declares the README-default command, args, provider id, and extension table', () => {\n    expect(Pack.name).toBe('lsp-kotlin')\n    expect(Pack.PROVIDER_ID).toBe('kotlin')\n    expect(Pack.inject).toEqual(['fs', 'lsp', 'subprocess'])\n    expect(Pack.DEFAULT_COMMAND).toBe('kotlin-language-server')\n    expect([...Pack.DEFAULT_ARGS]).toEqual([])\n    expect({ ...Pack.DEFAULT_EXTENSION_TO_LANGUAGE }).toEqual({\".kt\":\"kotlin\",\".kts\":\"kotlin\"})\n  })\n\n  it('keeps defaults when no override is given and merges user overrides on top', () => {\n    const defaults = Pack.resolveServerConfig({})\n    expect(defaults.command).toBe('kotlin-language-server')\n    expect([...defaults.args]).toEqual([])\n    expect(defaults.extensionToLanguage).toEqual({\".kt\":\"kotlin\",\".kts\":\"kotlin\"})\n    const overridden = Pack.resolveServerConfig({ command: '/custom/server', args: ['-x'] })\n    expect(overridden.command).toBe('/custom/server')\n    expect([...overridden.args]).toEqual(['-x'])\n    expect(overridden.extensionToLanguage).toEqual({\".kt\":\"kotlin\",\".kts\":\"kotlin\"})\n  })\n})\n\n// Lane 2: missing-server fallback (offline) ---------------------------\ndescribe('dsh-lsp-kotlin missing-server fallback', () => {\n  let ctx: Context\n\n  beforeAll(async () => {\n    ctx = new Context()\n    await ctx.plugin(Lsp)\n    await ctx.plugin(LocalSubprocessRuntime)\n    await ctx.plugin(LocalFileSystem, { cwd: process.cwd() })\n    await ctx.plugin(Pack, { command: 'definitely-missing-kotlin-server-xyz' })\n  }, 20_000)\n\n  afterAll(async () => {\n    if (ctx) await ctx.fiber.dispose()\n  })\n\n  it('loads without throwing and fails queries with a structured LSP_UNAVAILABLE error', async () => {\n    const request: LspQueryRequest = {\n      operation: 'goToDefinition',\n      filePath: 'sample.kt',\n      position: { line: 0, character: 0 },\n      workspaceRoot: process.cwd(),\n    }\n    await expect(ctx.lsp.query(request)).rejects.toThrow(\n      expect.objectContaining({ code: 'LSP_UNAVAILABLE' }),\n    )\n  })\n})\n\n// Lane 3: real server (auto-skip when not installed) ------------------\ndescribe.skipIf(!installed)('dsh-lsp-kotlin real server (kotlin-language-server)', () => {\n  let ctx: Context\n  let ws: string\n  let root: string\n\n  beforeAll(async () => {\n    root = await realpath(await mkdtemp(join(tmpdir(), 'dsh-lsp-kotlin-')))\n    ws = join(root, 'proj')\n    await mkdir(ws)\n\n    await writeFile(join(ws, 'sample.kt'), [\n      'fun add(a: Int, b: Int): Int = a + b',\n      '',\n      'fun main() {',\n      '    val x = add(1, 2)',\n      '    println(x)',\n      '}',\n    ].join('\\n'))\n\n\n    ctx = new Context()\n    await ctx.plugin(Lsp)\n    await ctx.plugin(LocalSubprocessRuntime)\n    await ctx.plugin(LocalFileSystem, { cwd: process.cwd() })\n    await ctx.plugin(Pack)\n  }, 60_000)\n\n  afterAll(async () => {\n    if (ctx) await ctx.fiber.dispose()\n    if (root) await rm(root, { recursive: true, force: true })\n  })\n\n/** One-based helper mirroring the model contract; converted to zero-based positions here. */\n  function at(operation: LspQueryRequest['operation'], line1: number, char1: number, filePath = 'sample.kt'): LspQueryRequest {\n    return { operation, filePath, position: { line: line1 - 1, character: char1 - 1 }, workspaceRoot: ws }\n  }\n\n  it('goToDefinition resolves the definition at a call site', async () => {\n\n    // Line 4, col 13 is the symbol under test in sample.kt.\n    const result = await ctx.lsp.query(at('goToDefinition', 4, 13))\n    expect(result.kind).toBe('locations')\n    if (result.kind === 'locations') {\n      expect(result.locations.length).toBeGreaterThanOrEqual(1)\n    }\n  }, 60_000)\n\n  it('findReferences finds references to the symbol including its declaration', async () => {\n\n    // Line 1, col 5 is the symbol under test in sample.kt.\n    const result = await ctx.lsp.query(at('findReferences', 1, 5))\n    expect(result.kind).toBe('locations')\n    if (result.kind === 'locations') {\n      expect(result.locations.length).toBeGreaterThanOrEqual(1)\n    }\n  }, 60_000)\n\n  it('goToImplementation resolves the implementation of the symbol', async () => {\n\n    // Line 4, col 13 is the symbol under test in sample.kt.\n    const result = await ctx.lsp.query(at('goToImplementation', 4, 13))\n    expect(result.kind).toBe('locations')\n    if (result.kind === 'locations') {\n      expect(result.locations.length).toBeGreaterThanOrEqual(1)\n    }\n  }, 60_000)\n\n  it('returns hover information for a typed symbol', async () => {\n    // Hover on the declaring `add` name (line 1, col 5).\n    const result = await ctx.lsp.query(at('hover', 1, 5))\n    expect(result.kind).toBe('hover')\n    if (result.kind === 'hover') {\n      if (result.hover !== null) expect(result.hover.contents).toContain('add')\n    }\n  }, 60_000)\n})\n"
    }
